from collections import Counter,deque
def transform(g):
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    h,w=len(g),len(g[0])
    out=[[bg]*w for _ in g]
    seen=set()
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and (i,j) not in seen:
                c=g[i][j]; q=deque([(i,j)]); comp=[]; seen.add((i,j))
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==c and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                if len(comp)>1 and any((y+1,x) in set(comp) and (y,x+1) in set(comp) and (y+1,x+1) in set(comp) for y,x in comp):
                    ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                    for y in range(min(ys),max(ys)+1):
                        for x in range(min(xs),max(xs)+1):
                            out[y][x]=c
    return out
